@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const services={{ Illuminate\Support\Js::from($services->mapWithKeys(fn($s)=>[(string)$s->id=>['gu'=>$s->name_gu,'en'=>$s->name_en,'days'=>$s->estimated_days,'fee'=>$s->service_fee,'instructions'=>$s->notes,'requires_documents'=>$s->requires_property_documents,'docs'=>$s->activeRequiredDocuments->map(fn($d)=>['gu'=>$d->name_gu,'en'=>$d->name_en,'mandatory'=>$d->is_mandatory,'types'=>$d->allowed_file_types,'max_kb'=>$d->max_upload_size_kb])->values()]])) }};const select=document.getElementById('service_id'),empty=document.getElementById('service-empty'),content=document.getElementById('service-content'),time=document.getElementById('service-time'),fee=document.getElementById('service-fee'),meta=document.getElementById('service-meta'),docs=document.getElementById('service-docs'),instructions=document.getElementById('service-instructions'),list=document.getElementById('required-documents-list');function renderService(){const selected=[...select.selectedOptions].map(option=>services[option.value]).filter(Boolean);const s=selected.length?{gu:selected.map(item=>item.gu).join(" · "),en:selected.map(item=>item.en).join(" · "),days:Math.max(...selected.map(item=>item.days||0)),fee:selected.reduce((total,item)=>total+(Number(item.fee)||0),0),instructions:selected.map(item=>item.instructions).filter(Boolean).join(" | "),requires_documents:selected.some(item=>item.requires_documents),docs:selected.flatMap(item=>item.docs)}:null;empty.classList.toggle('d-none',!!s);content.classList.toggle('d-none',!s);if(!s)return;document.getElementById('documents').required=false;document.getElementById('service-gu').textContent=s.gu;document.getElementById('service-en').textContent=s.en;time.classList.toggle('d-none',!s.days);fee.classList.toggle('d-none',s.fee===null||s.fee==='');meta.classList.toggle('d-none',!s.days&&(s.fee===null||s.fee===''));if(s.days)time.querySelector('strong').textContent=`${s.days} day(s)`;if(s.fee!==null&&s.fee!=='')fee.querySelector('strong').textContent=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(s.fee);instructions.classList.toggle('d-none',!s.instructions);instructions.querySelector('span').textContent=s.instructions||'';list.replaceChildren();s.docs.forEach(d=>{const li=document.createElement('li'),i=document.createElement('i'),span=document.createElement('span'),strong=document.createElement('strong'),small=document.createElement('small');i.className='bi bi-file-earmark-check';li.className=d.mandatory?'document-required':'document-optional';strong.textContent=d.gu;small.textContent=d.en+' '+(d.mandatory?'Required':'Optional');small.className='badge '+(d.mandatory?'text-bg-danger':'text-bg-secondary');span.append(strong,small);li.append(i,span);list.append(li)});docs.classList.toggle('d-none',!s.docs.length)}select.addEventListener('change',renderService);renderService();const input=document.getElementById('documents'),zone=document.getElementById('upload-dropzone'),files=document.getElementById('selected-files'),error=document.getElementById('file-error');function renderFiles(){const selected=[...input.files];files.replaceChildren();const invalid=selected.find(f=>!['pdf','jpg','jpeg','png'].includes(f.name.split('.').pop().toLowerCase())||f.size>10485760);error.textContent=selected.length>10?'Please select no more than 10 files.':invalid?'Each file must be PDF, JPG, JPEG or PNG and no larger than 10 MB.':'';error.classList.toggle('d-none',!error.textContent);selected.forEach(f=>{const li=document.createElement('li');li.textContent=`${f.name} · ${(f.size/1048576).toFixed(2)} MB`;files.append(li)});files.classList.toggle('d-none',!selected.length)}input.addEventListener('change',renderFiles);['dragenter','dragover'].forEach(n=>zone.addEventListener(n,e=>{e.preventDefault();zone.classList.add('is-dragging')}));['dragleave','drop'].forEach(n=>zone.addEventListener(n,e=>{e.preventDefault();zone.classList.remove('is-dragging')}));zone.addEventListener('drop',e=>{input.files=e.dataTransfer.files;renderFiles()});document.getElementById('customer-request-form').addEventListener('submit',()=>{const b=document.getElementById('submit-request');b.disabled=true;b.querySelector('.submit-label').classList.add('d-none');b.querySelector('.submit-loading').classList.remove('d-none')})});
</script>@endpush
